/*
 External links (defined as all links pointing to a domain that is not the
 same as the one from which the current document is being served)
 will have their 'target' attribute set to '_blank'.
 Social media sharing links will show in a popup.
 */
import { doesStringContainAny, getElements } from './functional';
/**
 * This ensures all links to external sites are _blank'd and have the relevant rel properties set
 */

export function externalLinks() {
  const links = getElements('a'); // If the link starts with any of these things, we'll open a 600x300 popup
  // window for them.

  const usePopupPrefixes = ['https://twitter.com/intent/tweet?', 'https://www.facebook.com/sharer.php?', 'https://www.linkedin.com/shareArticle?'];
  const thisDomain = window.location.hostname.indexOf('www.') === 0 ? window.location.hostname.substr(4) : window.location.hostname;
  links.forEach(link => {
    const href = link.getAttribute('href');

    if (!href || href.indexOf('mailto:') >= 0 || doesStringContainAny(href, ['http://', 'https://', '//']) === false) {
      return;
    }

    const domain = link.hostname.indexOf('www.') === 0 ? link.hostname.substr(4) : link.hostname;

    if (domain !== thisDomain) {
      link.setAttribute('target', '_blank'); // Add noopener and 'noreferrer' to work around this:
      // https://dev.to/ben/the-targetblank-vulnerability-by-example

      let rel = link.getAttribute('rel');

      if (!rel) {
        // will be null if it is not set
        rel = '';
      }

      link.setAttribute('rel', "".concat(rel, " noopener noreferrer"));
    } // Use a popup for social sharing links.
    // eslint-disable-next-line no-unused-vars


    for (const prefix of usePopupPrefixes) {
      if (href.indexOf(prefix) === 0) {
        link.addEventListener('click', event => {
          event.preventDefault();
          window.open(href, '_blank', 'width=600,height=300,menubar=0,toolbar=0,status=0');
        });
        break;
      }
    }
  });
}
/**
 * Gets the offsetTop of the passed element relevant to it's offsetParent
 *
 * @param {HTMLElement|Element} el - The element we'll be getting the offsetTop for
 * @param {Document|HTMLElement} [parent=HTMLBodyElement] - The offsetParent we want to get the offsetTop relative to
 * @param {Number} [offsetTop=0] - The starting offsetTop. This tends to be 0 but given this is a
 *   recursive function, we need to pass it to let it build up
 *
 * @returns {Number}
 */

export function getOffsetTop(el, parent = document.body, offsetTop = 0) {
  if (!isNaN(el.offsetTop)) {
    offsetTop += el.offsetTop;
  }

  return el.offsetParent === parent ? offsetTop : getOffsetTop(el.offsetParent, parent, offsetTop);
}
/**
 * Gets the offsetLeft of the passed element relevant to it's offsetParent
 *
 * @param {HTMLElement|Element} el - The element we'll be getting the offsetLeft for
 * @param {Document|HTMLElement} [parent=HTMLBodyElement] - The offsetParent we want to get the offsetLeft relative to
 * @param {Number} [offsetLeft=0] - The starting offsetLeft. This tends to be 0 but given this is a
 *   recursive function, we need to pass it to let it build up
 *
 * @returns {Number}
 */

export function getOffsetLeft(el, parent = document.body, offsetLeft = 0) {
  if (!isNaN(el.offsetLeft)) {
    offsetLeft += el.offsetLeft;
  }

  return el.offsetParent === parent ? offsetLeft : getOffsetLeft(el.offsetParent, parent, offsetLeft);
}
export const easingEquations = {
  easeOutSine(pos) {
    return Math.sin(pos * (Math.PI / 2));
  },

  easeInOutSine(pos) {
    return -0.5 * (Math.cos(Math.PI * pos) - 1);
  },

  easeInOutQuint(pos) {
    if ((pos /= 0.5) < 1) {
      return 0.5 * Math.pow(pos, 5);
    }

    return 0.5 * (Math.pow(pos - 2, 5) + 2);
  }

};
/**
 * This scrolls down to a specified point using a bezier curve
 *
 * @param {Number} scrollTargetY - Where we want the scroll to finish
 * @param {Number} [speed=300] - In all honesty, not sure what this controls even though it says speed..
 * @param {String} [easing=easeInOutQuint] - The type of bezier curve we want to use
 *
 * @returns {Promise}
 */

export function scrollToY(scrollTargetY = 0, speed = 300, easing = 'easeInOutQuint') {
  // eslint-disable-next-line compat/compat
  const scrollY = window.scrollY || window.pageYOffset;
  let currentTime = 0;
  const time = Math.max(0.1, Math.min(Math.abs(scrollY - scrollTargetY) / speed, 0.8));

  function tick() {
    currentTime += 1 / 60;
    const position = currentTime / time;
    const t = easingEquations[easing](position);

    if (position < 1) {
      window.requestAnimationFrame(tick);
      window.scrollTo(0, scrollY + (scrollTargetY - scrollY) * t);
    } else {
      window.scrollTo(0, scrollTargetY);
    }
  }

  tick();
}
/**
 * Creates a class we can use to cycle through items in sequential order
 */

export class Cycler {
  constructor(items) {
    this.items = items;
    this.currentPosition = 0;
  }

  current() {
    return this.items[this.currentPosition];
  }

  set(val) {
    this.currentPosition = val;
  }

  prev() {
    const current = this.current();
    this.currentPosition = this.currentPosition - 1;
    if (this.currentPosition < 0) this.currentPosition = this.items.length - 1;
    return current;
  }

  next() {
    const current = this.current();
    this.currentPosition = (this.currentPosition + 1) % this.items.length;
    return current;
  }

}
/**
 * Ensures a function doesn't run more than 1 per {wait}ms
 *
 * @param {Function} func - The function we'll be running
 * @param {Number} wait - How long to wait until running the function again
 * @param {Boolean} [immediate=false] - If `immediate` is passed, trigger the function on the leading edge,
 *   instead of the trailing.
 *
 * @returns {Number}
 */

export function debounce(func, wait, immediate = false) {
  let timeout;
  return function () {
    const context = this;
    const args = arguments;

    const later = function () {
      timeout = null;
      if (!immediate) func.apply(context, args);
    };

    const callNow = immediate && !timeout;
    clearTimeout(timeout);
    timeout = setTimeout(later, wait);
    if (callNow) func.apply(context, args);
  };
}
/**
 * A vanilla equivalent of jquery's $(el).slideDown()
 *
 * @param {HTMLElement|Element} el - The element we'll be animating
 * @param {Number} end - The number we want to end the slide at
 * @param {Number} [start=0] - Where we want to start the slide from, normally 0
 * @param {String} [easing=easeInOutQuint] - The type of bezier curve we want to use
 * @param {Number} [speed=300] - How long we want the animation to take..ish?
 *
 * @returns {Promise}
 */

export function slideDown(el, end, {
  start = 0,
  easing = 'easeInOutQuint',
  speed = 300
} = {}) {
  let currentPosition = 0;
  const time = Math.max(0.1, Math.min(Math.abs(end) / speed, 0.8));
  return new Promise((resolve, reject) => {
    const tick = () => {
      currentPosition += 1 / 60;
      const position = currentPosition / time;
      const t = easingEquations[easing](position);

      if (position < 1) {
        window.requestAnimationFrame(tick);
        el.style.height = "".concat(start + (end - start) * t, "px");
      } else {
        el.style.height = "".concat(end, "px");
        resolve();
      }
    };

    tick();
  });
}
/**
 * A vanilla equivalent of jquery's $(el).slideUp()
 *
 * @param {HTMLElement|Element} el - The element we'll be animating
 * @param {Number} start - Where we want to start the slide from, normally 0
 * @param {Number} [end=0] - The number we want to end the slide at
 * @param {String} [easing=easeInOutQuint] - The type of bezier curve we want to use
 * @param {Number} [speed=300] - How long we want the animation to take..ish?
 *
 * @returns {Promise}
 */

export function slideUp(el, start, {
  end = 0,
  easing = 'easeInOutQuint',
  speed = 300
} = {}) {
  let currentPosition = 0;
  const time = Math.max(0.1, Math.min(Math.abs(start) / speed, 0.8));
  const easingEquations = {
    easeOutSine(t) {
      return Math.sin(t * (Math.PI / 2));
    },

    easeInOutSine(t) {
      return -0.5 * (Math.cos(Math.PI * t) - 1);
    },

    easeInOutQuint(t) {
      return (t /= 0.5) < 1 ? 0.5 * Math.pow(t, 5) : 0.5 * (Math.pow(t - 2, 5) + 2);
    }

  };
  return new Promise((resolve, reject) => {
    const tick = () => {
      currentPosition += 1 / 60;
      const position = currentPosition / time;
      const t = easingEquations[easing](position);

      if (position < 1) {
        window.requestAnimationFrame(tick);
        el.style.height = "".concat(start - (start - end) * t, "px");
      } else {
        el.style.height = "".concat(end, "px");
        resolve();
      }
    };

    tick();
  });
}